query:
SELECT ?m ?nis ?coord ?end ?dissolved ?pl ?nl ?fr ?en ?mul WHERE {
  {
    ?m p:P31 ?st . ?st ps:P31 wd:Q493522 .
    OPTIONAL { ?st pq:P582 ?end }
  } UNION {
    # Gminy zniesione przy fuzjach: część ma inną klasę („gmina dawna”), ale zachowuje kod NIS.
    ?m wdt:P1567 ?anyNis ; wdt:P576 ?dissolvedAt ; wdt:P17 wd:Q31 .
    FILTER(?dissolvedAt >= "2018-12-31T00:00:00Z"^^xsd:dateTime)
  }
  OPTIONAL { ?m wdt:P576 ?dissolved }
  OPTIONAL { ?m wdt:P1567 ?nis }
  OPTIONAL { ?m wdt:P625 ?coord }
  OPTIONAL { ?m rdfs:label ?pl FILTER(LANG(?pl)="pl") }
  OPTIONAL { ?m rdfs:label ?nl FILTER(LANG(?nl)="nl") }
  OPTIONAL { ?m rdfs:label ?fr FILTER(LANG(?fr)="fr") }
  OPTIONAL { ?m rdfs:label ?en FILTER(LANG(?en)="en") }
  OPTIONAL { ?m rdfs:label ?mul FILTER(LANG(?mul)="mul") }
}
